import type { WordEntry } from '../types';

export type StageId =
  | 'tones'
  | 'sounds'
  | 'syllables'
  | 'words'
  | 'phrases'
  | 'conversation';

export type LessonKind = 'listen_repeat' | 'minimal_pair' | 'tone_drill' | 'dictation';

export type LessonItem = {
  /** traditional|simplified|pinyin OR plain hanzi for auto-pinyin */
  raw: string;
  hint?: string;
};

export type Lesson = {
  id: string;
  stageId: StageId;
  title: string;
  subtitle: string;
  kind: LessonKind;
  /** Estimated minutes */
  minutes: number;
  items: LessonItem[];
  unlockAfter?: string[]; // lesson ids that should be done first (soft)
};

export type Stage = {
  id: StageId;
  order: number;
  title: string;
  goal: string;
  color: string;
};

/** Longer windows while building muscle memory. earFirst = scene packs / warmup (phrase timing). */
export function listenSecondsForLesson(lesson: Lesson | undefined, earFirst = false): number {
  if (!lesson) return earFirst ? 14 : 10;
  if (lesson.id === 'fluency-checkpoint') return 18;
  if (lesson.kind === 'dictation') return 14;
  if (lesson.stageId === 'tones' || lesson.kind === 'tone_drill') return 14;
  if (lesson.stageId === 'sounds' || lesson.kind === 'minimal_pair') return 12;
  if (lesson.stageId === 'syllables') return 11;
  if (lesson.stageId === 'conversation') return 16;
  if (lesson.stageId === 'phrases') return 14;
  return 10;
}

/** Per-item window: longer for long sentences so fluency practice isn't cut off */
export function listenSecondsForItem(
  lesson: Lesson | undefined,
  hanziLen: number,
  earFirst = false,
): number {
  const base = listenSecondsForLesson(lesson, earFirst);
  if (hanziLen <= 1) {
    // Tones need more time: wait out noisy interim + soft retry
    const toneish = lesson?.stageId === 'tones' || lesson?.kind === 'tone_drill';
    return base + (toneish ? 4 : 2);
  }
  if (hanziLen <= 2) return base;
  if (hanziLen <= 6) return base + 2;
  if (hanziLen <= 12) return base + 4;
  return Math.min(28, base + 6 + Math.floor((hanziLen - 12) / 4));
}

/** Soft gate: stage unlocks when previous stage is ≥ half complete */
export function isStageUnlocked(stageId: StageId, completedLessonIds: string[]): boolean {
  const stage = STAGES.find((s) => s.id === stageId);
  if (!stage || stage.order <= 1) return true;
  const prev = STAGES.find((s) => s.order === stage.order - 1);
  if (!prev) return true;
  const prevLessons = lessonsForStage(prev.id);
  if (prevLessons.length === 0) return true;
  const done = prevLessons.filter((l) => completedLessonIds.includes(l.id)).length;
  return done >= Math.ceil(prevLessons.length / 2);
}

/** Soft prereq: unlockAfter lessons recommended first (still playable) */
export function isLessonPrereqMet(lesson: Lesson, completedLessonIds: string[]): boolean {
  if (!lesson.unlockAfter?.length) return true;
  return lesson.unlockAfter.every((id) => completedLessonIds.includes(id));
}

export function shouldForcePreRead(lesson: Lesson): boolean {
  return (
    lesson.stageId === 'tones' ||
    lesson.stageId === 'sounds' ||
    lesson.stageId === 'phrases' ||
    lesson.stageId === 'conversation' ||
    lesson.kind === 'tone_drill' ||
    lesson.kind === 'minimal_pair' ||
    lesson.kind === 'dictation'
  );
}

export function stagePracticeTip(stageId: StageId | undefined): string | null {
  switch (stageId) {
    case 'tones':
      return '技巧：先睇聲調曲線，用手指喺空中畫軌跡再出聲。';
    case 'sounds':
      return '技巧：成對對比（例如知／資），聽差先跟讀。';
    case 'syllables':
      return '技巧：聲母 → 韻母 → 聲調，分三步拼出嚟。';
    case 'words':
      return '技巧：雙字詞注意第二字輕聲同連讀節奏。聽寫挑戰會隱藏漢字，靠聽力。';
    case 'phrases':
      return '技巧：整句跟讀，唔好逐字斷開；留意語氣。示範會播兩次。';
    case 'conversation':
      return '技巧：追求自然語速；聽完先喺腦內覆述再講。示範會播兩次。';
    default:
      return null;
  }
}

/** Per-lesson coaching (overrides stage tip when present) */
