export function getLesson(id: string): Lesson | undefined {
  return LESSONS.find((l) => l.id === id);
}

/** Soft unlockAfter lessons still missing */
export function lessonPrereqGaps(lesson: Lesson, completedLessonIds: string[]): Lesson[] {
  if (!lesson.unlockAfter?.length) return [];
  return lesson.unlockAfter
    .map((id) => getLesson(id))
    .filter((l): l is Lesson => Boolean(l) && !completedLessonIds.includes(l.id));
}

/** Soft prereqs still missing before 流利總複習 */
export function fluencyCheckpointGaps(completedLessonIds: string[]): Lesson[] {
  const checkpoint = getLesson('fluency-checkpoint');
  if (!checkpoint?.unlockAfter?.length) return [];
  return checkpoint.unlockAfter
    .map((id) => getLesson(id))
    .filter((l): l is Lesson => Boolean(l) && !completedLessonIds.includes(l.id));
}

export function lessonsForStage(stageId: StageId): Lesson[] {
  return LESSONS.filter((l) => l.stageId === stageId);
}

export function lessonToDictionary(lesson: Lesson): string[] {
  return lesson.items.map((item) => item.raw);
}

export function parseLessonHint(lesson: Lesson, index: number): string | undefined {
  return lesson.items[index % lesson.items.length]?.hint;
}

/** Prefer ear-check dictation / scene unlocked by the just-finished lesson, else first incomplete. */
export function recommendNextLesson(
  completedLessonIds: string[],
  justFinishedId?: string | null,
): Lesson {
  const incomplete = LESSONS.filter((l) => !completedLessonIds.includes(l.id));
  if (justFinishedId) {
    const followDictation = incomplete.find(
      (l) => l.kind === 'dictation' && l.unlockAfter?.includes(justFinishedId),
    );
    if (followDictation) return followDictation;
    const followScene = incomplete.find(
      (l) =>
        (l.stageId === 'conversation' || l.stageId === 'phrases') &&
        l.unlockAfter?.includes(justFinishedId),
    );
    if (followScene) return followScene;
  }
  return incomplete[0] ?? LESSONS[LESSONS.length - 1];
}

/** Two-lesson daily chain: clear soft prereqs of the suggested next, then that next / follow-up. */
export function recommendDailyPlan(completedLessonIds: string[], justFinishedId?: string | null): Lesson[] {
  const suggested = recommendNextLesson(completedLessonIds, justFinishedId);
  const gaps = lessonPrereqGaps(suggested, completedLessonIds);
  const first = gaps[0] ?? suggested;
  const afterFirst = [...completedLessonIds, first.id];
  const second =
    first.id !== suggested.id
      ? suggested
      : recommendNextLesson(afterFirst, first.id);
  if (second.id === first.id) return [first];
  return [first, second];
}

export function curriculumStats(): { lessons: number; minutes: number } {
  return {
    lessons: LESSONS.length,
    minutes: LESSONS.reduce((sum, l) => sum + l.minutes, 0),
  };
}

export function estimatePathProgress(completedLessonIds: string[]): {
  stageId: StageId;
  percent: number;
  completed: number;
  total: number;
} {
  const total = LESSONS.length;
  const completed = completedLessonIds.filter((id) => LESSONS.some((l) => l.id === id)).length;
  const percent = total === 0 ? 0 : Math.round((completed / total) * 100);

  let stageId: StageId = 'tones';
  for (const stage of STAGES) {
    const stageLessons = lessonsForStage(stage.id);
    const done = stageLessons.every((l) => completedLessonIds.includes(l.id));
    stageId = stage.id;
    if (!done) break;
  }

  return { stageId, percent, completed, total };
}

export type { WordEntry };
